cat >> target/src/orchestration/tools/registry.test.ts <<EOF

  it('reports the correct path for nested property validation failures', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested-tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {
            user: {
              type: 'object',
              properties: {
                details: {
                  type: 'object',
                  properties: {
                    age: {type: 'number'},
                  },
                },
              },
            },
          },
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('nested-tool', {
      user: {details: {age: 'not-a-number'}},
    });

    expect(response.result).toContain('/user/details/age');
    expect(response.result).toContain('number');
  });
EOF
